create extension if not exists pgcrypto;
create type public.content_status as enum ('draft','published','archived');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, role text not null default 'student' check (role in ('student','admin')), created_at timestamptz not null default now());
create table public.exams (id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,description text,notification_url text,notification_year integer,status public.content_status not null default 'draft',created_at timestamptz not null default now());
create table public.subjects (id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,description text,status public.content_status not null default 'draft',created_at timestamptz not null default now());
create table public.topics (id uuid primary key default gen_random_uuid(),subject_id uuid not null references public.subjects(id) on delete cascade,slug text not null,title text not null,position integer not null default 0,status public.content_status not null default 'draft',unique(subject_id,slug));
create table public.chapters (id uuid primary key default gen_random_uuid(),topic_id uuid not null references public.topics(id) on delete cascade,title text not null,position integer not null default 0,status public.content_status not null default 'draft');
create table public.lessons (id uuid primary key default gen_random_uuid(),chapter_id uuid not null references public.chapters(id) on delete cascade,title text not null,content jsonb not null default '{}'::jsonb,status public.content_status not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.questions (id uuid primary key default gen_random_uuid(),lesson_id uuid references public.lessons(id) on delete set null,topic_id uuid references public.topics(id) on delete set null,prompt text not null,explanation text not null,correct_option smallint not null check(correct_option between 0 and 3),difficulty text not null default 'medium' check(difficulty in ('easy','medium','hard')),provenance text not null default 'original' check(provenance in ('original','verified_previous_year')),source_id uuid,year integer,shift text,marks numeric not null default 1,negative_marks numeric not null default 0,status public.content_status not null default 'draft',created_at timestamptz not null default now());
create table public.question_options(question_id uuid not null references public.questions(id) on delete cascade,position smallint not null check(position between 0 and 3),text text not null,primary key(question_id,position));
create table public.mock_tests(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,exam_id uuid references public.exams(id),duration_seconds integer not null check(duration_seconds>0),status public.content_status not null default 'draft',created_at timestamptz not null default now());
create table public.mock_test_questions(test_id uuid not null references public.mock_tests(id) on delete cascade,question_id uuid not null references public.questions(id) on delete cascade,position integer not null,primary key(test_id,question_id),unique(test_id,position));
create table public.test_attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,test_id uuid not null references public.mock_tests(id),started_at timestamptz not null default now(),submitted_at timestamptz,score numeric,correct_count integer not null default 0,incorrect_count integer not null default 0,unanswered_count integer not null default 0,seconds_spent integer not null default 0);
create table public.test_answers(attempt_id uuid not null references public.test_attempts(id) on delete cascade,question_id uuid not null references public.questions(id),selected_option smallint check(selected_option between 0 and 3),marked_for_review boolean not null default false,primary key(attempt_id,question_id));
create table public.bookmarks(user_id uuid not null references auth.users(id) on delete cascade,question_id uuid not null references public.questions(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,question_id));
create table public.learning_progress(user_id uuid not null references auth.users(id) on delete cascade,lesson_id uuid not null references public.lessons(id) on delete cascade,completed_at timestamptz,last_seen_at timestamptz not null default now(),primary key(user_id,lesson_id));
create table public.content_sources(id uuid primary key default gen_random_uuid(),name text not null,url text not null,verified_at timestamptz,notes text);
alter table public.questions add constraint questions_source_fk foreign key(source_id) references public.content_sources(id);
create table public.current_affairs(id uuid primary key default gen_random_uuid(),title text not null,body text not null,published_on date not null,source_id uuid references public.content_sources(id),status public.content_status not null default 'draft',created_at timestamptz not null default now());
create index topics_subject_idx on public.topics(subject_id,position);create index chapters_topic_idx on public.chapters(topic_id,position);create index questions_topic_idx on public.questions(topic_id,status);create index attempts_user_idx on public.test_attempts(user_id,started_at desc);create index current_affairs_date_idx on public.current_affairs(published_on desc);
-- Public visitors can read published educational content. Answer keys remain unavailable to anon/authenticated client roles.
alter table public.exams enable row level security;alter table public.subjects enable row level security;alter table public.topics enable row level security;alter table public.chapters enable row level security;alter table public.lessons enable row level security;alter table public.questions enable row level security;alter table public.question_options enable row level security;alter table public.mock_tests enable row level security;alter table public.mock_test_questions enable row level security;alter table public.test_attempts enable row level security;alter table public.test_answers enable row level security;alter table public.bookmarks enable row level security;alter table public.learning_progress enable row level security;alter table public.current_affairs enable row level security;alter table public.content_sources enable row level security;alter table public.profiles enable row level security;
create policy "published exams readable" on public.exams for select using(status='published');create policy "published subjects readable" on public.subjects for select using(status='published');create policy "published topics readable" on public.topics for select using(status='published');create policy "published chapters readable" on public.chapters for select using(status='published');create policy "published lessons readable" on public.lessons for select using(status='published');create policy "published current affairs readable" on public.current_affairs for select using(status='published');
create policy "own profile read" on public.profiles for select to authenticated using(id=auth.uid());create policy "own profile update" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "own attempts read" on public.test_attempts for select to authenticated using(user_id=auth.uid());create policy "own attempts create" on public.test_attempts for insert to authenticated with check(user_id=auth.uid());create policy "own attempts update" on public.test_attempts for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own answers read" on public.test_answers for select to authenticated using(exists(select 1 from public.test_attempts a where a.id=attempt_id and a.user_id=auth.uid()));create policy "own answers insert" on public.test_answers for insert to authenticated with check(exists(select 1 from public.test_attempts a where a.id=attempt_id and a.user_id=auth.uid()));create policy "own answers update" on public.test_answers for update to authenticated using(exists(select 1 from public.test_attempts a where a.id=attempt_id and a.user_id=auth.uid()));
create policy "own bookmarks all" on public.bookmarks for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "own progress all" on public.learning_progress for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
-- Do not grant client select on questions, question_options, test definitions, or source records.
